export const CRITERIA=[['mission','Encaix amb la missió',40],['impact','Impacte econòmic',25],['capacity','Capacitat d’execució',20],['ease','Càrrega assumible',15]];
export const STAGES=['Pendent','Validant requisits','En preparació','Presentada','Concedida','No concedida','Descartada'];
export const DEFAULT_WEIGHTS=[40,25,20,15];
export function score(row,weights){const sum=weights.reduce((a,b)=>a+b,0);return sum?Math.round(row.scores.reduce((v,s,i)=>v+s*weights[i],0)/sum*20):null;}
export function todayMadrid(now=new Date()){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Madrid'}).format(now);}
export function status(row,now=new Date()){if(row.status==='Oberta'&&row.deadline&&new Date(row.deadline)<now)return 'Tancada';return row.status;}
export function rank(rows,weights,work={}){return rows.filter(r=>r.kind==='Subvenció'&&work[r.id]?.stage!=='Descartada'&&r.gate!=='No elegible').map(r=>({...r,score:score(r,weights)})).sort((a,b)=>(b.score??-1)-(a.score??-1)||a.name.localeCompare(b.name,'ca'));}
export function budget(total,rate,cap,advance,hours,hourly){const grant=Math.min(total*rate/100,cap);return{grant,own:total-grant,initial:Math.max(0,total-grant*advance/100),admin:hours*hourly};}
export function cell(value){let s=String(value??'');if(/^\s*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
export function csv(rows,weights,work){const columns=['Ajut','Àmbit','Tipus','Projecte','Estat oficial','Termini','Entitat','Import','Finançament','Proposta orientativa','Encaix','Riscos','Com i quan','Documentació','Font oficial','Segona font','Data de revisió','Prioritat orientativa /100','Estat de treball','Requisits validats per usuari','Responsable','Data interna','Notes'];return '\ufeff'+[columns,...rows.map(r=>[r.name,r.area,r.kind,r.project,status(r),r.deadline??'',r.entity,r.amount,r.funding,r.proposal,r.fit,r.risk,r.steps,r.docs,r.source,r.source2??'',r.checked,score(r,weights),work[r.id]?.stage??'Pendent',work[r.id]?.validated?'Sí':'No',work[r.id]?.owner??'',work[r.id]?.due??'',work[r.id]?.notes??''])].map(r=>r.map(cell).join(';')).join('\r\n');}
export function validateBackup(obj,ids){if(!obj||obj.version!==1||!Array.isArray(obj.weights)||obj.weights.length!==4||!obj.weights.every(v=>Number.isFinite(v)&&v>=0&&v<=100)||!obj.work||typeof obj.work!=='object'||Array.isArray(obj.work))throw Error('Còpia no vàlida.');const work={};for(const [id,w]of Object.entries(obj.work)){if(!ids.includes(id)||!w||typeof w!=='object'||!STAGES.includes(w.stage)||typeof w.validated!=='boolean')throw Error('Fitxa o estat no vàlid.');for(const k of ['owner','due','notes'])if(typeof w[k]!=='string'||w[k].length>(k==='notes'?6000:200))throw Error('Camp no vàlid.');if(w.due&&!/^\d{4}-\d{2}-\d{2}$/.test(w.due))throw Error('Data no vàlida.');work[id]={stage:w.stage,validated:w.validated,owner:w.owner,due:w.due,notes:w.notes};}return{version:1,weights:[...obj.weights],work};}

